 'logis+sin+expt*P^d': lambda p: p[0]*np.sin(p[1]*s)+p[2]*P*(1-P/p[3])+p[4]*np.exp(p[5]*t)*P**p[6],
 'logis+sin+cos*P': lambda p: p[0]*np.sin(p[1]*s)+p[2]*P*(1-P/p[3])+p[4]*np.cos(p[5]*t)*P**p[6],
 'logis(t)+sin': lambda p: p[0]*np.sin(p[1]*s)+p[2]*P*(1-P/p[3])+p[4]*t**p[5],
}
rng=np.random.default_rng(1)
